-- Labels and their Vintages: the catalogue's two levels (ADR-0003).
--
-- Generated by `drizzle-kit generate` from `db/schema.ts`, then finished by hand with what
-- Drizzle does not write: the function the grapes check calls, above the tables, and below
-- them the comments and the triggers that hold what a check cannot — a rule that reads a
-- second table.

-- Every entry of a list says something: no null, no '', no padding. A check constraint may
-- not hold a subquery, so the walk over the array is a function, and it is immutable because
-- it reads nothing but its argument.
create function every_one_is_said(entries text[])
returns boolean language sql immutable
as $$
  select coalesce(bool_and(e is not null and e = btrim(e) and e <> ''), true)
    from unnest(entries) as e;
$$;
