-- **A Label always has at least one Vintage** (ADR-0003). Deferred to the end of the
-- transaction, because a Label and its first Vintage are two inserts and the Label must
-- come first; and on the Vintage side so that moving or deleting the last one is refused
-- too — unless the Label is going with it, which is what merging two Labels does.
create function a_label_has_a_vintage() returns trigger
language plpgsql
as $$
declare
  label text;
begin
  if tg_table_name = 'labels' then
    label := new.id;
  else
    label := old.label_id;
  end if;

  if exists (select 1 from labels where id = label)
     and not exists (select 1 from vintages where label_id = label) then
    raise exception 'a Label has at least one Vintage'
      using errcode = 'check_violation',
            constraint = 'labels_have_a_vintage';
  end if;

  return null;
end;
$$;
--> statement-breakpoint
comment on function a_label_has_a_vintage() is
  'A Label always has at least one Vintage (ADR-0003), checked at commit so that a Label and its first Vintage can be written in either order.';
--> statement-breakpoint
create constraint trigger labels_have_a_vintage
  after insert on labels
  deferrable initially deferred
  for each row execute function a_label_has_a_vintage();
--> statement-breakpoint
create constraint trigger vintages_leave_their_label_one
  after delete or update of label_id on vintages
  deferrable initially deferred
  for each row execute function a_label_has_a_vintage();
--> statement-breakpoint

-- **A Label of a Kind without vintages has exactly one Vintage, NV** (ADR-0002, ADR-0010):
-- spirits, beer, sake. The Kind carries the fact (`kinds.has_vintages`), so the rule is
-- asked of the Kind's row and never of a list of names. *At most one NV* is already
-- `vintages_one_nv_per_label` and *at least one* is `labels_have_a_vintage`, so what is left
-- to say here is only that it is NV.
create function a_vintage_suits_its_labels_kind() returns trigger
language plpgsql
as $$
begin
  if new.dating <> 'nv' and exists (
    select 1 from labels l join kinds k on k.id = l.kind_id
     where l.id = new.label_id and not k.has_vintages
  ) then
    raise exception 'a Label of a Kind without vintages has only its NV Vintage'
      using errcode = 'check_violation',
            constraint = 'vintages_of_a_kind_without_vintages_are_nv';
  end if;

  return null;
end;
$$;
--> statement-breakpoint
comment on function a_vintage_suits_its_labels_kind() is
  'A Label whose Kind has no vintages has exactly one Vintage, NV (ADR-0002, ADR-0010). The Kind carries the fact, in has_vintages.';
--> statement-breakpoint
create trigger vintages_of_a_kind_without_vintages_are_nv
  after insert or update of dating, year, label_id on vintages
  for each row execute function a_vintage_suits_its_labels_kind();
--> statement-breakpoint

-- The same rule seen from the Label: moving a Label to a Kind without vintages while it
-- still has a year or an unknown is refused, rather than leaving a whisky with a 2019.
-- The owner moves or merges those Vintages first; nothing is converted behind their back,
-- because an unknown turned into NV would state something false about the bottle.
create function a_labels_kind_suits_its_vintages() returns trigger
language plpgsql
as $$
begin
  if new.kind_id is distinct from old.kind_id
     and exists (select 1 from kinds k where k.id = new.kind_id and not k.has_vintages)
     and exists (select 1 from vintages v where v.label_id = new.id and v.dating <> 'nv') then
    raise exception 'that Kind has no vintages, and this Label has a year or an unknown'
      using errcode = 'check_violation',
            constraint = 'labels_kind_without_vintages_keeps_only_nv';
  end if;

  return null;
end;
$$;
--> statement-breakpoint
comment on function a_labels_kind_suits_its_vintages() is
  'A Label cannot move to a Kind without vintages while it has a year or an unknown Vintage (ADR-0010).';
--> statement-breakpoint
create trigger labels_kind_without_vintages_keeps_only_nv
  after update of kind_id on labels
  for each row execute function a_labels_kind_suits_its_vintages();
--> statement-breakpoint

-- And seen from the Kind: a Kind cannot stop having vintages while a Label of it has one.
-- Kinds are rows a later migration may change (ADR-0002), so this is the same invariant at
-- the third table it spans.
create function a_kinds_vintages_suit_its_labels() returns trigger
language plpgsql
as $$
begin
  if old.has_vintages and not new.has_vintages and exists (
    select 1 from labels l join vintages v on v.label_id = l.id
     where l.kind_id = new.id and v.dating <> 'nv'
  ) then
    raise exception 'a Label of this Kind has a year or an unknown Vintage'
      using errcode = 'check_violation',
            constraint = 'kinds_has_vintages_holds_what_its_labels_have';
  end if;

  return null;
end;
$$;
--> statement-breakpoint
comment on function a_kinds_vintages_suit_its_labels() is
  'A Kind cannot stop having vintages while a Label of it has a year or an unknown Vintage (ADR-0010).';
--> statement-breakpoint
create trigger kinds_has_vintages_holds_what_its_labels_have
  after update of has_vintages on kinds
  for each row execute function a_kinds_vintages_suit_its_labels();
